Azure Service Bus.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Azure Service Bus", "Azure Service Bus") {
    Component("Claim Submission Topic", "Claim Submission Topic", "Azure Service Bus Topic", "Receives published claim events from the Migration Router via AMQP/TLS and handles routing filter rules.")
    Component("Mainframe Relay Queues", "Mainframe Relay Queues", "Azure Service Bus Queue", "Queues messages to forward them to the Mainframe Integration Adapter via AMQP/HTTPS.")
    Component("Dead-Letter Subsystems", "Dead-Letter Subsystems", "Azure Service Bus Dead-Letter Queue", "Captures and isolates undeliverable messages to ensure zero data loss requirements (R-04).")
    Component("Routing Filter Rules", "Routing Filter Rules", "Azure Service Bus Filters", "Evaluates and directs messages to appropriate downstream queues based on claim type and migration status.")
}

Rel("Claim Submission Topic", "Mainframe Relay Queues", "Forwards messages")
Rel("Claim Submission Topic", "Dead-Letter Subsystems", "Routes failed messages")
Rel("Routing Filter Rules", "Claim Submission Topic", "Applies routing logic")
@enduml

Azure Cache for Redis.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Azure Cache for Redis", "Azure Cache for Redis") {
    Component("Redis Cache Engine", "Redis Cache Engine", "Azure Cache for Redis", "In-memory data store engine providing high-throughput and low-latency access for performance optimization.")
    Component("Distributed Output Cache Provider", "Distributed Output Cache Provider", ".NET Core Distributed Caching", "Provides distributed output caching support to accelerate response times across API endpoints.")
    Component("Claim State Cache Manager", "Claim State Cache Manager", ".NET Core Caching Service", "Manages transient claim state caching to ensure fast retrieval during active adjuster workflows.")
}

Rel("Distributed Output Cache Provider", "Redis Cache Engine", "Reads and writes cached HTTP outputs via RESP over TCP/TLS", "RESP over TCP/TLS")
Rel("Claim State Cache Manager", "Redis Cache Engine", "Stores and invalidates claim session states via RESP over TCP/TLS", "RESP over TCP/TLS")
@enduml
